42. spec fn cache_lru_of<K, V>(entries: alloc::collections::BTreeMap<K, CacheEntry<V>>) -> Seq<K> {
43.     if btreemap_view_spec(entries).dom().len() == 0 {
44.         Seq::empty()
45.     } else {
